def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Extend any diagonal run of at least two matching non-background cells backwards to border.
    for r in range(h):
      for c in range(w):
       col=g[r][c]
       if col==5: continue
       for dr,dc in ((1,1),(1,-1)):
        if 0<=r+dr<h and 0<=c+dc<w and g[r+dr][c+dc]==col:
         rr,cc=r-dr,c-dc
         while 0<=rr<h and 0<=cc<w:
          if g[rr][cc]==5: g[rr][cc]=col
          rr-=dr; cc-=dc
    return g
